230. //==================================================================================================
231. 
232. /// Pure, field-level reconstruction of `Inner::view()` from its component spec values
233. /// (`set_bits`, `num_bits`, `refcount` sequence). This lets the single-frame transition lemmas
234. /// reason about the abstract view purely in terms of bitmap/refcount values, without passing
235. /// `&Inner` snapshots around.
236. closed spec fn view_of(set_bits: Set<int>, num_bits: int, refcount: Seq<u8>) -> FrameAllocView {
237.     FrameAllocView {
238.         allocated_frames: Set::new(|addr: int|
239.             exists|i: int| #[trigger] set_bits.contains(i) && addr == frame_addr_of(i)
240.         ),
241.         free_frames: Set::new(|addr: int|
242.             exists|i: int| {
243.                 &&& 0 <= i < num_bits
244.                 &&& !#[trigger] set_bits.contains(i)
245.                 &&& addr == frame_addr_of(i)
246.             }
247.         ),
248.         refcounts: Map::new(
249.             |addr: int|
250.                 exists|i: int| #[trigger] set_bits.contains(i) && addr == frame_addr_of(i),
251.             |addr: int| refcount[addr / spec_page_size()] as int,
252.         ),
253.     }
254. }
255. 
256. /// `Inner::view()` equals `view_of` applied to its own bitmap/refcount component values.
257. proof fn lemma_view_of(inner: &Inner)
258.     ensures
259.         inner@ == view_of(inner.bitmap@.set_bits, inner.bitmap@.num_bits, spec_refcount_seq(inner)),
260. {
261.     let v = view_of(inner.bitmap@.set_bits, inner.bitmap@.num_bits, spec_refcount_seq(inner));
262.     assert(inner@.allocated_frames =~= v.allocated_frames);
263.     assert(inner@.free_frames =~= v.free_frames);
264.     assert(inner@.refcounts =~= v.refcounts);
265.     assert(inner@ == v);
266. }
267. 
268. /// Reserve one frame: setting a previously-clear, in-range bit and writing its refcount to 1
269. /// moves the frame from `free` to `allocated` with refcount 1.
270. proof fn lemma_reserve_one_v(sb: Set<int>, nb: int, rc: Seq<u8>, fnx: int, addr: int)
271.     requires
272.         spec_page_size() > 0,
273.         addr % spec_page_size() == 0,
274.         fnx == addr / spec_page_size(),
275.         0 <= fnx < nb,
276.         !sb.contains(fnx),
277.     ensures
278.         view_of(sb.insert(fnx), nb, rc.update(fnx, 1u8)) == (FrameAllocView {
279.             allocated_frames: view_of(sb, nb, rc).allocated_frames.insert(addr),
280.             free_frames: view_of(sb, nb, rc).free_frames.remove(addr),
281.             refcounts: view_of(sb, nb, rc).refcounts.insert(addr, 1int),
282.         }),
283. {
284.     lemma_aligned_addr_index(addr);
285.     assert(frame_addr_of(fnx) == addr);
286.     let pre = view_of(sb, nb, rc);
287.     let rc2 = rc.update(fnx, 1u8);
288.     let post = view_of(sb.insert(fnx), nb, rc2);
289. 
290.     assert(post.allocated_frames =~= pre.allocated_frames.insert(addr)) by {
291.         assert forall|a: int| post.allocated_frames.contains(a)
292.             implies pre.allocated_frames.insert(addr).contains(a) by {
293.             let i = choose|i: int| #[trigger] sb.insert(fnx).contains(i) && a == frame_addr_of(i);
294.             assert(sb.insert(fnx).contains(i) && a == frame_addr_of(i));
295.             if i != fnx {
296.                 assert(sb.contains(i));
297.             }
298.         }
299.         assert forall|a: int| pre.allocated_frames.insert(addr).contains(a)
300.             implies post.allocated_frames.contains(a) by {
301.             if a == addr {
302.                 assert(sb.insert(fnx).contains(fnx) && a == frame_addr_of(fnx));
303.             } else {
304.                 let i = choose|i: int| #[trigger] sb.contains(i) && a == frame_addr_of(i);
305.                 assert(sb.insert(fnx).contains(i) && a == frame_addr_of(i));
306.             }
307.         }
308.     }
309. 
310.     assert(post.free_frames =~= pre.free_frames.remove(addr)) by {
311.         assert forall|a: int| post.free_frames.contains(a)
312.             implies pre.free_frames.remove(addr).contains(a) by {
313.             let i = choose|i: int|
314.                 0 <= i < nb && !(#[trigger] sb.insert(fnx).contains(i)) && a == frame_addr_of(i);
315.             assert(0 <= i < nb && !sb.insert(fnx).contains(i) && a == frame_addr_of(i));
316.             assert(i != fnx);
317.             lemma_frame_addr_injective_ne(i, fnx);
318.             assert(!sb.contains(i));
319.         }
320.         assert forall|a: int| pre.free_frames.remove(addr).contains(a)
321.             implies post.free_frames.contains(a) by {
322.             let i = choose|i: int|
323.                 0 <= i < nb && !(#[trigger] sb.contains(i)) && a == frame_addr_of(i);
324.             assert(0 <= i < nb && !sb.contains(i) && a == frame_addr_of(i));
325.             assert(i != fnx);
326.             assert(!sb.insert(fnx).contains(i));
327.         }
328.     }
329. 
330.     assert(post.refcounts =~= pre.refcounts.insert(addr, 1int)) by {
331.         assert(post.refcounts.dom() =~= pre.refcounts.insert(addr, 1int).dom()) by {
332.             assert(post.allocated_frames =~= pre.allocated_frames.insert(addr));
333.         }
334.         assert forall|a: int| post.refcounts.dom().contains(a)
335.             implies #[trigger] post.refcounts[a] == pre.refcounts.insert(addr, 1int)[a] by {
336.             let i = choose|i: int| #[trigger] sb.insert(fnx).contains(i) && a == frame_addr_of(i);
337.             assert(sb.insert(fnx).contains(i) && a == frame_addr_of(i));
338.             lemma_frame_addr_div(i);
339.             assert(a / spec_page_size() == i);
340.             if a == addr {
341.                 assert(rc2[fnx] == 1u8);
342.             } else {
343.                 assert(i != fnx);
344.                 assert(rc2[i] == rc[i]);
345.             }
346.         }
347.     }
348. 
349.     assert(post == FrameAllocView {
350.         allocated_frames: pre.allocated_frames.insert(addr),
351.         free_frames: pre.free_frames.remove(addr),
352.         refcounts: pre.refcounts.insert(addr, 1int),
353.     });
354. }
355. 
356. /// Release one frame's last reference: clearing a previously-set, in-range bit and writing its
357. /// refcount to 0 moves the frame from `allocated` back to `free` and drops its refcount entry.
358. proof fn lemma_release_one_v(sb: Set<int>, nb: int, rc: Seq<u8>, fnx: int, addr: int)
359.     requires
360.         spec_page_size() > 0,
361.         addr % spec_page_size() == 0,
362.         fnx == addr / spec_page_size(),
363.         0 <= fnx < nb,
364.         sb.contains(fnx),
365.     ensures
366.         view_of(sb.remove(fnx), nb, rc.update(fnx, 0u8)) == (FrameAllocView {
367.             allocated_frames: view_of(sb, nb, rc).allocated_frames.remove(addr),
368.             free_frames: view_of(sb, nb, rc).free_frames.insert(addr),
369.             refcounts: view_of(sb, nb, rc).refcounts.remove(addr),
370.         }),
371. {
372.     lemma_aligned_addr_index(addr);
373.     assert(frame_addr_of(fnx) == addr);
374.     let pre = view_of(sb, nb, rc);
375.     let rc2 = rc.update(fnx, 0u8);
376.     let post = view_of(sb.remove(fnx), nb, rc2);
377. 
378.     assert(post.allocated_frames =~= pre.allocated_frames.remove(addr)) by {
379.         assert forall|a: int| post.allocated_frames.contains(a)
380.             implies pre.allocated_frames.remove(addr).contains(a) by {
381.             let i = choose|i: int| #[trigger] sb.remove(fnx).contains(i) && a == frame_addr_of(i);
382.             assert(sb.remove(fnx).contains(i) && a == frame_addr_of(i));
383.             assert(i != fnx);
384.             lemma_frame_addr_injective_ne(i, fnx);
385.             assert(sb.contains(i));
386.         }
387.         assert forall|a: int| pre.allocated_frames.remove(addr).contains(a)
388.             implies post.allocated_frames.contains(a) by {
389.             let i = choose|i: int| #[trigger] sb.contains(i) && a == frame_addr_of(i);
390.             assert(sb.contains(i) && a == frame_addr_of(i));
391.             assert(i != fnx);
392.             assert(sb.remove(fnx).contains(i));
393.         }
394.     }
395. 
396.     assert(post.free_frames =~= pre.free_frames.insert(addr)) by {
397.         assert forall|a: int| post.free_frames.contains(a)
398.             implies pre.free_frames.insert(addr).contains(a) by {
399.             let i = choose|i: int|
400.                 0 <= i < nb && !(#[trigger] sb.remove(fnx).contains(i)) && a == frame_addr_of(i);
401.             assert(0 <= i < nb && !sb.remove(fnx).contains(i) && a == frame_addr_of(i));
402.             if i != fnx {
403.                 assert(!sb.contains(i));
404.             }
405.         }
406.         assert forall|a: int| pre.free_frames.insert(addr).contains(a)
407.             implies post.free_frames.contains(a) by {
408.             if a == addr {
409.                 assert(0 <= fnx < nb && !sb.remove(fnx).contains(fnx) && a == frame_addr_of(fnx));
410.             } else {
411.                 let i = choose|i: int|
412.                     0 <= i < nb && !(#[trigger] sb.contains(i)) && a == frame_addr_of(i);
413.                 assert(0 <= i < nb && !sb.contains(i) && a == frame_addr_of(i));
414.                 assert(!sb.remove(fnx).contains(i));
415.             }
416.         }
417.     }
418. 
419.     assert(post.refcounts =~= pre.refcounts.remove(addr)) by {
420.         assert(post.refcounts.dom() =~= pre.refcounts.remove(addr).dom()) by {
421.             assert(post.allocated_frames =~= pre.allocated_frames.remove(addr));
422.         }
423.         assert forall|a: int| post.refcounts.dom().contains(a)
424.             implies #[trigger] post.refcounts[a] == pre.refcounts.remove(addr)[a] by {
425.             let i = choose|i: int| #[trigger] sb.remove(fnx).contains(i) && a == frame_addr_of(i);
426.             assert(sb.remove(fnx).contains(i) && a == frame_addr_of(i));
427.             assert(i != fnx);
428.             lemma_frame_addr_div(i);
429.             assert(a / spec_page_size() == i);
430.             assert(rc2[i] == rc[i]);
431.         }
432.     }
433. 
434.     assert(post == FrameAllocView {
435.         allocated_frames: pre.allocated_frames.remove(addr),
436.         free_frames: pre.free_frames.insert(addr),
437.         refcounts: pre.refcounts.remove(addr),
438.     });
439. }
440. 
441. /// Update one allocated frame's refcount in place: rewriting a set, in-range bit's refcount slot
442. /// (the bit stays set) leaves the allocated/free partition unchanged and updates the refcount map.
443. proof fn lemma_update_refcount_v(sb: Set<int>, nb: int, rc: Seq<u8>, fnx: int, addr: int, nv: u8)
444.     requires
445.         spec_page_size() > 0,
446.         addr % spec_page_size() == 0,
447.         fnx == addr / spec_page_size(),
448.         0 <= fnx < nb,
449.         sb.contains(fnx),
450.     ensures
451.         view_of(sb, nb, rc.update(fnx, nv)) == (FrameAllocView {
452.             allocated_frames: view_of(sb, nb, rc).allocated_frames,
453.             free_frames: view_of(sb, nb, rc).free_frames,
454.             refcounts: view_of(sb, nb, rc).refcounts.insert(addr, nv as int),
455.         }),
456. {
457.     lemma_aligned_addr_index(addr);
458.     assert(frame_addr_of(fnx) == addr);
459.     let pre = view_of(sb, nb, rc);
460.     let rc2 = rc.update(fnx, nv);
461.     let post = view_of(sb, nb, rc2);
462. 
463.     assert(post.allocated_frames =~= pre.allocated_frames);
464.     assert(post.free_frames =~= pre.free_frames);
465. 
466.     assert(post.refcounts =~= pre.refcounts.insert(addr, nv as int)) by {
467.         assert(pre.allocated_frames.contains(addr)) by {
468.             assert(sb.contains(fnx) && addr == frame_addr_of(fnx));
469.         }
470.         assert(post.refcounts.dom() =~= pre.refcounts.insert(addr, nv as int).dom());
471.         assert forall|a: int| post.refcounts.dom().contains(a)
472.             implies #[trigger] post.refcounts[a] == pre.refcounts.insert(addr, nv as int)[a] by {
473.             let i = choose|i: int| #[trigger] sb.contains(i) && a == frame_addr_of(i);
474.             assert(sb.contains(i) && a == frame_addr_of(i));
475.             lemma_frame_addr_div(i);
476.             assert(a / spec_page_size() == i);
477.             if a == addr {
478.                 assert(rc2[fnx] == nv);
479.             } else {
480.                 assert(i != fnx);
481.                 assert(rc2[i] == rc[i]);
482.             }
483.         }
484.     }
485. 
486.     assert(post == FrameAllocView {
487.         allocated_frames: pre.allocated_frames,
488.         free_frames: pre.free_frames,
489.         refcounts: pre.refcounts.insert(addr, nv as int),
490.     });
491. }
492. 
493. /// Contrapositive helper of `lemma_frame_addr_injective`: distinct indices have distinct frame
494. /// addresses (used to discharge `frame_addr_of(i) != addr` side conditions).
495. proof fn lemma_frame_addr_injective_ne(i: int, j: int)
496.     requires
497.         spec_page_size() > 0,
498.         i != j,
499.     ensures
500.         frame_addr_of(i) != frame_addr_of(j),
501. {
502.     if frame_addr_of(i) == frame_addr_of(j) {
503.         lemma_frame_addr_injective(i, j);
504.     }
505. }
506. 
507. }
508.

