             allocated_frames: view_of(sb, nb, rc).allocated_frames.remove(addr),
             free_frames: view_of(sb, nb, rc).free_frames.insert(addr),
             refcounts: view_of(sb, nb, rc).refcounts.remove(addr),
         }),
