         assert forall|a: int| post.free_frames.contains(a)
             implies pre.free_frames.insert(addr).contains(a) by {
             let i = choose|i: int|
                 0 <= i < nb && !(#[trigger] sb.remove(fnx).contains(i)) && a == frame_addr_of(i);
